//! Public funding — and the one number that decides whether to write the bid or take the contract.
//!
//! Grants and government contracts are the least-competed money available to a small technical
//! operator, and the reason is unglamorous: the paperwork deters people. A solicitation with four
//! bidders and one with four hundred pay the same, and which one you are looking at is knowable
//! before you spend a week on it.
//!
//! **The bid is priced against the hour it costs.** An award is not revenue, it is a lottery ticket
//! with a known price: the hours to write it. So every opportunity here is reduced to ONE comparable
//! figure — expected value per hour of bid effort — and that figure is compared against the hourly a
//! contract would pay for the same hours. A $150,000 grant at a 10% hit rate costing 80 hours is
//! $187/hour of expectation; the same 80 hours contracting at $120 is $9,600 CERTAIN. Which is
//! better depends on the runway, and that is a computation rather than an opinion.
//!
//! # Three refusals, because each is a way to waste a week
//!
//! 1. **Not eligible is not ranked.** An opportunity you cannot legally win has no expected value,
//!    and leaving it in the list to be sorted by size puts the biggest unwinnable thing at the top.
//! 2. **An unknown hit rate is not a guess.** Where no evidence supports a probability, the expected
//!    value is ABSENT and the row says so. A default of 10% would be a number somebody acts on.
//! 3. **A deadline you cannot make is a refusal, not a discount.** Bidding late is bidding zero, and
//!    a solicitation needing 80 hours in the next 5 days is not a 60%-confidence opportunity, it is
//!    a no with extra steps.
use crate::money::{money, scale, Money, Rounding};

/// Where an opportunity came from. All PUBLIC — no credentials, no scraping, no ToS exposure.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FundingSource {
    pub id: &'static str,
    pub name: &'static str,
    /// What it actually lists, in words, so the roster is readable without opening anything.
    pub carries: &'static str,
    /// The documented public API base. UNVERIFIED until somebody has called it — see `verified`.
    pub api: Option<&'static str>,
    /// FALSE until a real call has been made and the response shape checked.
    pub verified: bool,
    pub caveat: &'static str,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Vehicle {
    /// Non-dilutive research funding — the highest award-to-competition ratio available here.
    Sbir,
    /// A grant: awarded, not bought. Usually the longest cycle.
    Grant,
    /// A contract for work, competed.
    Contract,
    /// A pre-competed vehicle you can be added to.
    Idiq,
    /// A state or local request for proposal — thinner competition, faster cycles.
    Rfp,
}

impl Vehicle {
    pub fn label(self) -> &'static str {
        match self {
            Vehicle::Sbir => "sbir",
            Vehicle::Grant => "grant",
            Vehicle::Contract => "contract",
            Vehicle::Idiq => "idiq",
            Vehicle::Rfp => "rfp",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Opportunity {
    pub id: String,
    pub title: String,
    pub source_id: String,
    pub vehicle: Vehicle,
    /// The ceiling, where one is published. ABSENT means unstated — not zero.
    pub award: Option<Money>,
    /// `YYYY-MM-DD`.
    pub closes: String,
    /// Hours to produce a credible submission. The real price of the ticket.
    pub bid_hours: f64,
    /// 0-1. ABSENT unless something actually supports it — a default here is a lie with a number.
    pub hit_rate: Option<f64>,
    /// Requirements that must ALL hold, as plain assertions about you.
    pub requires: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verdict {
    Biddable,
    Ineligible,
    TooLate,
    Unpriceable,
}

impl Verdict {
    pub fn label(self) -> &'static str {
        match self {
            Verdict::Biddable => "biddable",
            Verdict::Ineligible => "ineligible",
            Verdict::TooLate => "too-late",
            Verdict::Unpriceable => "unpriceable",
        }
    }

    fn rank(self) -> u8 {
        match self {
            Verdict::Biddable => 0,
            Verdict::Unpriceable => 1,
            Verdict::Ineligible => 2,
            Verdict::TooLate => 3,
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Assessment {
    pub opportunity: Opportunity,
    pub verdict: Verdict,
    /// `award × hit_rate`. ABSENT when either is.
    pub expected: Option<Money>,
    /// The comparable number: expected value per hour of bid effort.
    pub per_hour: Option<Money>,
    /// What contracting those same hours would pay, for the comparison that decides it.
    pub contracting_alternative: Money,
    /// True when the bid beats simply billing the hours.
    pub beats_contracting: bool,
    pub hours_available: f64,
    /// Why it is not biddable, when it is not.
    pub why: Option<String>,
    pub unmet: Vec<String>,
}

pub struct AssessOptions<'a> {
    /// `YYYY-MM-DD`. Passed in, never read from a clock.
    pub as_of: &'a str,
    /// What the bidder can truthfully assert.
    pub capabilities: &'a [(String, bool)],
    /// Billable hourly the same effort could earn instead — the opportunity cost, and the whole
    /// comparison.
    pub contracting_rate: Money,
    /// Hours per week available for bid writing.
    pub hours_per_week: f64,
}

impl<'a> AssessOptions<'a> {
    pub fn new(as_of: &'a str, capabilities: &'a [(String, bool)], contracting_rate: Money) -> Self {
        AssessOptions { as_of, capabilities, contracting_rate, hours_per_week: 20.0 }
    }
}

/// The public sources.
///
/// EVERY ONE IS UNVERIFIED — the endpoints are recorded from documentation, not from a call — and
/// `verified` says so on each, the same discipline the institution profiles use. A scanner that
/// reported nothing because a URL moved would look identical to a quiet week.
pub const FUNDING_SOURCES: &[FundingSource] = &[
    FundingSource {
        id: "sbir",
        name: "SBIR / STTR",
        carries: "federal research solicitations across ~11 agencies; non-dilutive, Phase I typically the entry point",
        api: Some("https://api.www.sbir.gov/public/api/"),
        verified: false,
        caveat: "the highest award-to-competition ratio on this list, and the one whose eligibility rules are strictest — check ownership and size standards FIRST, not last",
    },
    FundingSource {
        id: "grants-gov",
        name: "Grants.gov",
        carries: "every federal grant opportunity, all agencies",
        api: Some("https://api.grants.gov/v1/api/"),
        verified: false,
        caveat: "volume is enormous and most of it is irrelevant — the eligibility gate is doing the real work here, not the search",
    },
    FundingSource {
        id: "sam-gov",
        name: "SAM.gov",
        carries: "federal contract opportunities, notices and awards; registration is required to BID but not to search",
        api: Some("https://api.sam.gov/opportunities/v2/"),
        verified: false,
        caveat: "requires a free API key for programmatic access, and registration (UEI) before any bid can be submitted — start that early, it is slow",
    },
    FundingSource {
        id: "state-local",
        name: "State and local procurement",
        carries: "state, county and municipal RFPs — no single index, one portal per jurisdiction",
        api: None,
        verified: false,
        caveat: "thinner competition and faster cycles than federal, but there is no unified API; this is per-portal and partly manual",
    },
];

pub fn source_for(id: &str) -> Option<&'static FundingSource> {
    FUNDING_SOURCES.iter().find(|s| s.id == id)
}

/// Requirements the bidder cannot truthfully assert.
///
/// ABSENT is not YES. A capability nobody has recorded reads as unmet, which costs a bid you might
/// have won and never costs one you could not.
pub fn unmet_requirements(o: &Opportunity, capabilities: &[(String, bool)]) -> Vec<String> {
    o.requires
        .iter()
        .filter(|r| !capabilities.iter().any(|(k, v)| k == *r && *v))
        .cloned()
        .collect()
}

fn days_between(a: &str, b: &str) -> f64 {
    crate::txn::days_between(a, b) as f64
}

/// Price one opportunity, and REFUSE rather than discount.
///
/// The order is the point: eligibility, then the deadline, then the arithmetic. Something you cannot
/// win or cannot submit has no expected value at all, and computing one for it would put an
/// unwinnable thing at the top of a list sorted by size.
pub fn assess(o: &Opportunity, opts: &AssessOptions) -> Assessment {
    let contracting_alternative = scale(opts.contracting_rate, o.bid_hours, Rounding::HalfUp);
    let days_left = days_between(opts.as_of, &o.closes);
    let hours_available = ((days_left / 7.0) * opts.hours_per_week).max(0.0);

    let base = |verdict: Verdict, why: Option<String>, unmet: Vec<String>| Assessment {
        opportunity: o.clone(),
        verdict,
        expected: None,
        per_hour: None,
        contracting_alternative,
        beats_contracting: false,
        hours_available,
        why,
        unmet,
    };

    let unmet = unmet_requirements(o, opts.capabilities);
    if !unmet.is_empty() {
        let why = format!(
            "cannot truthfully assert: {} — an opportunity you cannot legally win has no expected value, so it is not ranked at all",
            unmet.join(", ")
        );
        return base(Verdict::Ineligible, Some(why), unmet);
    }

    if days_left < 0.0 {
        return base(Verdict::TooLate, Some(format!("closed {} day(s) ago", -days_left as i64)), Vec::new());
    }
    if hours_available < o.bid_hours {
        // A deadline you cannot make is a refusal, not a discount. Bidding late is bidding zero.
        let why = format!(
            "needs {}h and there are {}h before it closes — bidding late is bidding zero, so this is a no rather than a lower-confidence yes",
            o.bid_hours,
            hours_available.floor()
        );
        return base(Verdict::TooLate, Some(why), Vec::new());
    }

    let (Some(award), Some(hit_rate)) = (o.award, o.hit_rate) else {
        // UNKNOWN IS NOT A GUESS. A default hit rate is a number somebody would act on.
        let why = if o.award.is_none() {
            "no award ceiling is published, so there is nothing to multiply — find the number before spending the hours"
        } else {
            "nothing supports a hit rate for this, and a default would be a fabricated number somebody acts on"
        };
        return base(Verdict::Unpriceable, Some(why.to_string()), Vec::new());
    };

    let expected_minor = (award.minor as f64 * hit_rate).round() as i64;
    let per_hour_minor = if o.bid_hours > 0.0 { (expected_minor as f64 / o.bid_hours).round() as i64 } else { expected_minor };
    Assessment {
        opportunity: o.clone(),
        verdict: Verdict::Biddable,
        expected: Some(money(expected_minor, award.currency)),
        per_hour: Some(money(per_hour_minor, award.currency)),
        contracting_alternative,
        beats_contracting: per_hour_minor > opts.contracting_rate.minor,
        hours_available,
        why: None,
        unmet: Vec::new(),
    }
}

/// Everything, best first — and the unbiddable KEPT, at the bottom, with the reason.
///
/// Dropping them would make the list shorter and the same opportunity would be re-found,
/// re-assessed and re-rejected next week. THE REASON IS THE DURABLE PART.
pub fn rank(opportunities: &[Opportunity], opts: &AssessOptions) -> Vec<Assessment> {
    let mut out: Vec<Assessment> = opportunities.iter().map(|o| assess(o, opts)).collect();
    out.sort_by(|a, b| {
        a.verdict
            .rank()
            .cmp(&b.verdict.rank())
            .then_with(|| b.per_hour.map(|m| m.minor).unwrap_or(-1).cmp(&a.per_hour.map(|m| m.minor).unwrap_or(-1)))
            .then_with(|| a.opportunity.closes.cmp(&b.opportunity.closes))
    });
    out
}

/// The ones worth the hours: biddable AND better than simply billing the same time.
pub fn worth_the_hours(assessments: &[Assessment]) -> Vec<&Assessment> {
    assessments.iter().filter(|a| a.verdict == Verdict::Biddable && a.beats_contracting).collect()
}

/// Total bid hours a plan commits to — the constraint people forget until they are inside it.
pub fn total_bid_hours(assessments: &[Assessment]) -> f64 {
    assessments.iter().map(|a| a.opportunity.bid_hours).sum()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Blocking {
    pub requirement: String,
    pub blocks: usize,
}

/// A capability nobody has asserted is the thing to go and fix.
///
/// Across everything ineligible, which requirement blocks the most? That is a work item — a
/// registration, a certification, a past-performance record — and it is usually cheaper than any
/// single bid it unblocks.
pub fn blocking_requirements(assessments: &[Assessment]) -> Vec<Blocking> {
    let mut counts: Vec<Blocking> = Vec::new();
    for a in assessments {
        for r in &a.unmet {
            match counts.iter_mut().find(|c| c.requirement == *r) {
                Some(c) => c.blocks += 1,
                None => counts.push(Blocking { requirement: r.clone(), blocks: 1 }),
            }
        }
    }
    counts.sort_by(|x, y| y.blocks.cmp(&x.blocks).then_with(|| x.requirement.cmp(&y.requirement)));
    counts
}

/// One line a person can act on.
pub fn summarise(a: &Assessment) -> String {
    let t = &a.opportunity.title;
    if a.verdict != Verdict::Biddable {
        return format!("{t} — {}: {}", a.verdict.label().to_uppercase(), a.why.clone().unwrap_or_default());
    }
    let verdict = if a.beats_contracting {
        format!("beats billing the same {}h", a.opportunity.bid_hours)
    } else {
        format!("does NOT beat billing the same {}h ({} certain)", a.opportunity.bid_hours, a.contracting_alternative.minor)
    };
    format!("{t} — {}/h of expectation, {verdict}", a.per_hour.map(|m| m.minor).unwrap_or(0))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY — no real solicitation reaches this repo.
    #[allow(clippy::too_many_arguments)]
    fn op(id: &str, title: &str, vehicle: Vehicle, award: Option<i64>, closes: &str, bid_hours: f64, hit_rate: Option<f64>, requires: &[&str]) -> Opportunity {
        Opportunity {
            id: id.to_string(),
            title: title.to_string(),
            source_id: "sbir".to_string(),
            vehicle,
            award: award.map(usd),
            closes: closes.to_string(),
            bid_hours,
            hit_rate,
            requires: requires.iter().map(|s| s.to_string()).collect(),
        }
    }

    fn caps() -> Vec<(String, bool)> {
        vec![("sam-registered".to_string(), true), ("us-owned".to_string(), true), ("past-performance".to_string(), false)]
    }

    #[test]
    fn every_source_is_marked_unverified_because_none_has_been_called() {
        assert_eq!(FUNDING_SOURCES.len(), 4);
        assert!(FUNDING_SOURCES.iter().all(|s| !s.verified), "a scanner reporting nothing because a URL moved looks identical to a quiet week");
        assert!(FUNDING_SOURCES.iter().all(|s| !s.caveat.is_empty()), "each says what it costs to use");
        assert_eq!(source_for("sbir").expect("sbir").name, "SBIR / STTR");
        assert!(source_for("state-local").expect("state-local").api.is_none(), "no unified API, and it says so by ABSENCE");
        assert!(source_for("nope").is_none());
    }

    #[test]
    fn a_bid_is_priced_per_hour_and_compared_against_billing_the_same_hours() {
        let c = caps();
        let o = AssessOptions::new("2026-06-30", &c, usd(12_000));
        let a = assess(&op("a", "SBIR Phase I", Vehicle::Sbir, Some(15_000_000), "2026-09-30", 80.0, Some(0.10), &["sam-registered"]), &o);
        assert_eq!(a.verdict, Verdict::Biddable);
        assert_eq!(a.expected.unwrap().minor, 1_500_000, "award x hit rate");
        assert_eq!(a.per_hour.unwrap().minor, 18_750, "the ONE comparable figure");
        assert_eq!(a.contracting_alternative.minor, 960_000, "80h at 120/h, CERTAIN");
        assert!(a.beats_contracting);
        assert!(summarise(&a).contains("beats billing the same 80h"));
    }

    #[test]
    fn a_bid_that_loses_to_simply_billing_the_hours_says_so_rather_than_being_hidden() {
        let c = caps();
        let o = AssessOptions::new("2026-06-30", &c, usd(12_000));
        let a = assess(&op("b", "Small grant", Vehicle::Grant, Some(500_000), "2026-09-30", 80.0, Some(0.10), &[]), &o);
        assert_eq!(a.verdict, Verdict::Biddable, "it IS biddable — it is just not worth it");
        assert_eq!(a.per_hour.unwrap().minor, 625);
        assert!(!a.beats_contracting);
        assert!(summarise(&a).contains("does NOT beat billing the same 80h (960000 certain)"));
    }

    #[test]
    fn something_you_cannot_win_is_not_ranked_at_all() {
        let c = caps();
        let o = AssessOptions::new("2026-06-30", &c, usd(12_000));
        // A $500,000 ceiling, and it produces NO expected value — leaving it in to be sorted by size
        // would put the biggest unwinnable thing at the top.
        let a = assess(&op("c", "Big contract", Vehicle::Contract, Some(50_000_000), "2026-12-31", 100.0, Some(0.2), &["past-performance", "sam-registered"]), &o);
        assert_eq!(a.verdict, Verdict::Ineligible);
        assert_eq!(a.unmet, vec!["past-performance"], "sam-registered IS asserted");
        assert!(a.expected.is_none() && a.per_hour.is_none());
        assert!(a.why.as_ref().unwrap().contains("has no expected value, so it is not ranked at all"));
        // A capability nobody recorded reads as UNMET, never as yes.
        let unknown = assess(&op("x", "x", Vehicle::Rfp, Some(1), "2026-12-31", 1.0, Some(0.5), &["never-heard-of-it"]), &o);
        assert_eq!(unknown.unmet, vec!["never-heard-of-it"]);
    }

    #[test]
    fn a_deadline_you_cannot_make_is_a_refusal_rather_than_a_discount() {
        let c = caps();
        let o = AssessOptions::new("2026-06-30", &c, usd(12_000));
        let closed = assess(&op("d", "Closed one", Vehicle::Rfp, Some(100_000), "2026-06-01", 10.0, Some(0.5), &[]), &o);
        assert_eq!(closed.verdict, Verdict::TooLate);
        assert_eq!(closed.why.as_deref(), Some("closed 29 day(s) ago"));

        // 5 days at 20h/week is 14 hours against 80 needed. NOT a lower-confidence yes.
        let rush = assess(&op("e", "Rush", Vehicle::Rfp, Some(100_000), "2026-07-05", 80.0, Some(0.5), &[]), &o);
        assert_eq!(rush.verdict, Verdict::TooLate);
        assert!(rush.why.as_ref().unwrap().contains("there are 14h before it closes"));
        assert!(rush.why.as_ref().unwrap().contains("bidding late is bidding zero"));
        assert!(rush.expected.is_none(), "no expected value is computed for something that cannot be submitted");
    }

    #[test]
    fn an_unknown_award_or_hit_rate_is_unpriceable_rather_than_defaulted() {
        let c = caps();
        let o = AssessOptions::new("2026-06-30", &c, usd(12_000));
        let no_award = assess(&op("f", "Unstated", Vehicle::Idiq, None, "2026-09-30", 20.0, Some(0.5), &[]), &o);
        assert_eq!(no_award.verdict, Verdict::Unpriceable);
        assert!(no_award.why.as_ref().unwrap().contains("nothing to multiply"));

        let no_rate = assess(&op("g", "Unknown odds", Vehicle::Grant, Some(100_000), "2026-09-30", 20.0, None, &[]), &o);
        assert_eq!(no_rate.verdict, Verdict::Unpriceable);
        // A default of 10% would be a number somebody ACTS on — that is the whole objection.
        assert!(no_rate.why.as_ref().unwrap().contains("a default would be a fabricated number somebody acts on"));
        assert!(no_rate.expected.is_none() && no_rate.per_hour.is_none());
    }

    #[test]
    fn the_ranking_keeps_the_rejects_at_the_bottom_with_their_reasons() {
        let c = caps();
        let o = AssessOptions::new("2026-06-30", &c, usd(12_000));
        let all = vec![
            op("a", "SBIR Phase I", Vehicle::Sbir, Some(15_000_000), "2026-09-30", 80.0, Some(0.10), &["sam-registered"]),
            op("b", "Small grant", Vehicle::Grant, Some(500_000), "2026-09-30", 80.0, Some(0.10), &[]),
            op("c", "Big contract", Vehicle::Contract, Some(50_000_000), "2026-12-31", 100.0, Some(0.2), &["past-performance"]),
            op("d", "Closed one", Vehicle::Rfp, Some(100_000), "2026-06-01", 10.0, Some(0.5), &[]),
            op("g", "Unknown odds", Vehicle::Grant, Some(100_000), "2026-09-30", 20.0, None, &[]),
            op("h", "Also blocked", Vehicle::Contract, Some(900_000), "2026-11-01", 30.0, Some(0.3), &["past-performance", "bonding"]),
        ];
        let r = rank(&all, &o);
        let got: Vec<(&str, &str)> = r.iter().map(|a| (a.opportunity.id.as_str(), a.verdict.label())).collect();
        assert_eq!(
            got,
            vec![("a", "biddable"), ("b", "biddable"), ("g", "unpriceable"), ("h", "ineligible"), ("c", "ineligible"), ("d", "too-late")]
        );
        assert_eq!(r.len(), all.len(), "nothing is DROPPED — the reason is the durable part");
        assert_eq!(worth_the_hours(&r).iter().map(|a| a.opportunity.id.as_str()).collect::<Vec<_>>(), vec!["a"]);
        assert_eq!(total_bid_hours(&r), 320.0, "the constraint people forget until they are inside it");
    }

    #[test]
    fn the_requirement_blocking_the_most_bids_is_the_work_item() {
        let c = caps();
        let o = AssessOptions::new("2026-06-30", &c, usd(12_000));
        let all = vec![
            op("c", "Big contract", Vehicle::Contract, Some(50_000_000), "2026-12-31", 100.0, Some(0.2), &["past-performance"]),
            op("h", "Also blocked", Vehicle::Contract, Some(900_000), "2026-11-01", 30.0, Some(0.3), &["past-performance", "bonding"]),
        ];
        let b = blocking_requirements(&rank(&all, &o));
        // One registration unblocks TWO bids, and is usually cheaper than either.
        assert_eq!(b, vec![Blocking { requirement: "past-performance".into(), blocks: 2 }, Blocking { requirement: "bonding".into(), blocks: 1 }]);
    }

    #[test]
    fn eligibility_is_checked_before_the_deadline_and_the_deadline_before_the_arithmetic() {
        let c = caps();
        let o = AssessOptions::new("2026-06-30", &c, usd(12_000));
        // Ineligible AND closed AND unpriceable at once. It reports INELIGIBLE, because that is the
        // one that makes the others irrelevant.
        let a = assess(&op("z", "Everything wrong", Vehicle::Rfp, None, "2026-01-01", 500.0, None, &["past-performance"]), &o);
        assert_eq!(a.verdict, Verdict::Ineligible);
        // Closed AND unpriceable: too-late wins, because you cannot submit it at any price.
        let b = assess(&op("y", "Closed and unpriced", Vehicle::Rfp, None, "2026-01-01", 5.0, None, &[]), &o);
        assert_eq!(b.verdict, Verdict::TooLate);
    }
}
